/** Real application/API/Chromium; the uncertain fixture was generated by the real worker using mock HTTP. */
import {chromium} from 'playwright-core';import assert from 'node:assert/strict';import {readFile,mkdir,writeFile} from 'node:fs/promises';
const base=process.env.WEB_BASE_URL||'http://127.0.0.1:3110',account=JSON.parse(await readFile('acceptance-evidence/ops-browser-account.json','utf8')),evidence=process.env.OPS_EVIDENCE_DIR||'docs/product-rebuild/evidence/operations-2026-10-20';await mkdir(evidence,{recursive:true});const browser=await chromium.launch({executablePath:process.env.CHROME_BIN||'/usr/bin/chromium',headless:true,args:['--no-sandbox','--disable-dev-shm-usage']}),page=await browser.newPage({viewport:{width:1366,height:1000}}),checks=[],errors=[];page.on('pageerror',e=>errors.push(e.message));await page.route('https://**',r=>r.abort());const check=s=>{checks.push(s);console.log('PASS '+s)},api=(path,method='GET',body)=>page.evaluate(async({path,method,body})=>{const response=await fetch('/api/v1'+path,{method,headers:{'content-type':'application/json','x-boat-csrf':'1'},...(body?{body:JSON.stringify(body)}:{})});return {status:response.status,data:await response.json()}},{path,method,body});
try{
 await page.goto(base);await page.locator('#login-form [name=tenantSlug]').fill(account.slug);await page.locator('#login-form [name=email]').fill(account.email);await page.locator('#login-form [name=password]').fill(account.password);await page.locator('#login-form').evaluate(f=>f.requestSubmit());await page.waitForFunction(()=>document.body.dataset.authReady==='true');await page.goto('about:blank');await page.goto(base+'/#bot/'+account.botId);await page.waitForSelector('.canvas-node');const path='/bots/'+account.botId+'/flow-requests',tracePath='/bots/'+account.botId+'/flow-traces/'+account.conversationId,before=(await api(tracePath)).data;
 await page.getByRole('button',{name:'طلبات الربط والتسوية',exact:true}).click();const dialog=page.getByRole('dialog',{name:'طلبات الربط والتسوية'});await dialog.locator('[data-request-job-id]').first().waitFor();assert.equal(await dialog.locator('[data-request-job-id]').count(),20);await dialog.getByRole('button',{name:'طلبات أقدم',exact:true}).click();await page.waitForFunction(()=>document.querySelectorAll('.builder-request-jobs [data-request-job-id]').length>20);assert.equal((await api(path)).status,200);check('real bot-scoped HTTP metadata and bounded older-page navigation render the saved request queue');
 await dialog.getByLabel('حالة طلبات الربط').selectOption('UNCERTAIN');await page.waitForFunction(()=>document.querySelectorAll('.builder-request-jobs [data-request-job-id]').length===1);const row=dialog.locator('[data-request-job-id="'+account.jobId+'"]');await row.getByRole('button',{name:'مراجعة النتيجة غير المؤكدة',exact:true}).waitFor();assert.equal((await api(path+'/'+account.jobId+'/reconcile','POST',{decision:'DELIVERED',acknowledged:false,expectedAttempts:1})).status,400);const metadata=(await api(path+'?status=UNCERTAIN')).data;assert.equal(JSON.stringify(metadata).includes('PRIVATE_REQUEST_FIXTURE'),false);await page.screenshot({path:evidence+'/uncertain-request-desktop.png'});check('actual uncertain state explains external verification; server rejects missing confirmation and excludes request/response content');
 await row.getByRole('button',{name:'مراجعة النتيجة غير المؤكدة',exact:true}).click();await row.getByLabel('النتيجة المؤكدة خارج المنصة').selectOption('DELIVERED');await row.getByLabel('راجعت الخدمة الخارجية وأفهم أن التسوية لا تعيد إرسال الطلب.').check();await row.getByRole('button',{name:'تأكيد التسوية دون إعادة إرسال',exact:true}).click();await page.waitForFunction(()=>document.getElementById('notice').textContent.includes('حُفظت التسوية'));await dialog.getByLabel('حالة طلبات الربط').selectOption('ALL');await row.getByText('تسوية يدوية موثقة: تم التأكد من الوصول',{exact:true}).waitFor();const repeat=await api(path+'/'+account.jobId+'/reconcile','POST',{decision:'DELIVERED',acknowledged:true,expectedAttempts:1});assert.equal(repeat.status,200);assert.equal(repeat.data.replayed,true);assert.equal(repeat.data.queued,0);assert.equal(repeat.data.resumed,false);const after=(await api(tracePath)).data;assert.deepEqual(after.snapshot,before.snapshot);assert.deepEqual(after.events,before.events);const job=(await api(path)).data.rows.find(r=>r.id===account.jobId);assert.equal(job.attempts,1);assert.equal(job.outcome,'TIMEOUT');assert.equal(job.status,'SENT');check('real form saves one verified resolution, idempotent HTTP retry, no extra attempt and identical flow snapshot/committed trace');
 for(const [width,height]of [[1366,1000],[390,844]]){await page.setViewportSize({width,height});await page.screenshot({path:evidence+'/reconciled-request-'+width+'.png'});assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+2))}
 await page.route('**/flow-requests?*',async route=>{await page.unroute('**/flow-requests?*');await route.abort('connectionfailed')},{times:1});await dialog.getByRole('button',{name:'تحديث الطلبات',exact:true}).click();await dialog.getByRole('button',{name:'إعادة المحاولة',exact:true}).waitFor();assert.ok(await dialog.locator('[data-request-job-id]').count()>0);await page.screenshot({path:evidence+'/request-retry-mobile.png'});await dialog.getByRole('button',{name:'إعادة المحاولة',exact:true}).click();await dialog.getByRole('button',{name:'تحديث الطلبات',exact:true}).waitFor();check('desktop/mobile real operations, retained-data failure and actual retry; no unsafe resend control');
 await dialog.getByRole('button',{name:'إغلاق',exact:true}).click();await page.locator('.bot-studio-back').click();await page.locator('.vessel-menu-button').click();await page.locator('#logout').click();await page.waitForFunction(()=>!document.getElementById('login').hidden);assert.equal(await page.locator('.builder-request-jobs').count(),0);assert.equal(await page.evaluate(()=>fetch('/api/v1/bots').then(r=>r.status)),401);assert.deepEqual(errors,[]);check('logout clears operation dialogs and authenticated access');await writeFile(evidence+'/results.json',JSON.stringify({checks,errors,chromium:browser.version(),date:new Date().toISOString()},null,2));
}catch(error){await page.screenshot({path:evidence+'/failure.png'});throw error}finally{await browser.close()}
